INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Analyse > Monitoring
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist Monitoring immer erforderlich, um die Leistung eines IT-Systems zu gewährleisten?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Überprüfungen sind möglich, aber weniger effizient"}, {"text": "Ja", "correct": false, "because": "Monitoring ist hilfreich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Monitoring potenzielle Probleme erkennen, bevor sie auftreten?', 2, '[{"text": "Ja", "correct": true, "because": "Proaktives Monitoring identifiziert Anomalien frühzeitig"}, {"text": "Nein", "correct": false, "because": "Monitoring hat präventive Fähigkeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Monitoring-Tools ständig aktiv sein, um nützlich zu sein?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitgesteuertes Monitoring kann ausreichend sein"}, {"text": "Ja", "correct": false, "because": "Dauerhaftigkeit ist oft nützlich, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Monitoring-Systeme die Systemleistung negativ beeinflussen?', 2, '[{"text": "Ja", "correct": true, "because": "Ressourcenverbrauch durch Monitoring ist möglich"}, {"text": "Nein", "correct": false, "because": "Einfluss hängt von Implementierung ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Monitoring unabhängig von der Größe eines IT-Systems effektiv?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierung und Anpassung sind erforderlich"}, {"text": "Ja", "correct": false, "because": "Systemgröße beeinflusst Monitoring-Ansatz"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird häufig für das Monitoring von Netzwerken und Servern verwendet?', 3, '[{"text": "Nagios", "correct": true, "because": "Weit verbreitet für Echtzeitüberwachung"}, {"text": "Notepad", "correct": false, "because": "Kein Monitoring-Tool"}, {"text": "Photoshop", "correct": false, "because": "Für Grafik, nicht Monitoring"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt wird typischerweise durch Monitoring überwacht?', 2, '[{"text": "Systemverfügbarkeit", "correct": true, "because": "Kernaufgabe des Monitorings"}, {"text": "Farbschema der GUI", "correct": false, "because": "Irrelevant"}, {"text": "Anzahl der Benutzerhandbücher", "correct": false, "because": "Nicht technisch relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Monitoring in der IT?', 2, '[{"text": "Erkennung von Leistungsproblemen", "correct": true, "because": "Frühwarnsystem für Störungen"}, {"text": "Erhöhung der Hardwarekosten", "correct": false, "because": "Nicht gewünscht"}, {"text": "Vermeidung von Dokumentation", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch fehlendes Monitoring übersehen werden?', 3, '[{"text": "Speicherüberlastung", "correct": true, "because": "Ohne Überwachung unbemerkt"}, {"text": "Schnellere Systemleistung", "correct": false, "because": "Kein Fehler"}, {"text": "Automatische Behebung", "correct": false, "because": "Nicht realistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Daten wird oft durch Monitoring gesammelt?', 2, '[{"text": "Leistungsmetriken", "correct": true, "because": "Zeigen Systemzustand an"}, {"text": "Benutzeranmeldungen", "correct": false, "because": "Nur bei spezifischem Fokus"}, {"text": "Farbcodes", "correct": false, "because": "Irrelevant"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten können durch Monitoring überwacht werden?', 4, '[{"text": "CPU-Auslastung", "correct": true, "because": "Misst Prozessorleistung"}, {"text": "Netzwerkverkehr", "correct": true, "because": "Erkennt Engpässe"}, {"text": "Speicherverbrauch", "correct": true, "because": "Überwacht RAM"}, {"text": "Bürobeleuchtung", "correct": false, "because": "Nicht IT-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Monitoring in einem IT-System?', 3, '[{"text": "Früherkennung von Problemen", "correct": true, "because": "Präventiv"}, {"text": "Optimierung der Ressourcennutzung", "correct": true, "because": "Effizienzsteigerung"}, {"text": "Reduktion von Ausfallzeiten", "correct": true, "because": "Schnelle Reaktion"}, {"text": "Geringere Benutzerfreundlichkeit", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools sind für Monitoring typisch?', 4, '[{"text": "Zabbix", "correct": true, "because": "Echtzeitüberwachung"}, {"text": "Prometheus", "correct": true, "because": "Metrikenbasiertes Monitoring"}, {"text": "Grafana", "correct": true, "because": "Visualisierung von Daten"}, {"text": "Excel", "correct": false, "because": "Keine Monitoring-Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können durch fehlendes Monitoring entstehen?', 3, '[{"text": "Unbemerkte Systemausfälle", "correct": true, "because": "Keine Warnung"}, {"text": "Performanceverlust", "correct": true, "because": "Unentdeckte Engpässe"}, {"text": "Sicherheitslücken", "correct": true, "because": "Angriffe unbemerkt"}, {"text": "Schnellere Reaktion", "correct": false, "because": "Gegenteil tritt ein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Monitoring-System effektiv?', 3, '[{"text": "Echtzeit-Daten", "correct": true, "because": "Aktuelle Informationen"}, {"text": "Alarmfunktionen", "correct": true, "because": "Warnungen bei Abweichungen"}, {"text": "Skalierbarkeit", "correct": true, "because": "Anpassung an Systemgröße"}, {"text": "Farbliche Gestaltung", "correct": false, "because": "Nicht funktional relevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Monitoring kann die Systemwartung proaktiv unterstützen. b) Monitoring ist nur für große Systeme sinnvoll.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Proaktiv ja, auch kleine Systeme profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Monitoring-Tools können Alarme bei Schwellenwertüberschreitung senden. b) Monitoring ersetzt die manuelle Problemanalyse vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alarme ja, Analyse ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Monitoring kann Netzwerkprobleme aufdecken. b) Monitoring-Tools sind immer kostenlos verfügbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerk ja, Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein gutes Monitoring-System liefert historische Daten. b) Monitoring ist unabhängig von der Hardwarekonfiguration.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Historie ja, Hardware relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Monitoring kann helfen, Ressourcenengpässe zu vermeiden. b) Monitoring-Systeme beheben Probleme automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Engpässe ja, Behebung manuell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

